    wire roundingMode_minMag      = (roundingMode == `GoldFpMulE8S23_round_minMag);
    wire roundingMode_min         = (roundingMode == `GoldFpMulE8S23_round_min);
    wire roundingMode_max         = (roundingMode == `GoldFpMulE8S23_round_max);
    wire roundingMode_near_maxMag = (roundingMode == `GoldFpMulE8S23_round_near_maxMag);
